ations'=>'Pemberitahuan','Cache Logged-in Users'=>'Cache Pengguna Log Masuk','Cache Commenters'=>'Komen Pemula Caching','Cache REST API'=>'API REST Cache','Cache Login Page'=>'Cache Halaman Log Masuk','Cache Mobile'=>'Kandar Mudah Alih','List of Mobile User Agents'=>'Senarai Ejen Pengguna Mudah Alih','Private Cached URIs'=>'URI Cached Peribadi','Drop Query String'=>'Gugurkan Rentetan Pertanyaan','Method'=>'Kaedah','Host'=>'Hos','Port'=>'Port','Default Object Lifetime'=>'Tempoh Hayat Objek Lalai','Username'=>'Nama pengguna','Password'=>'Kata Laluan','Redis Database ID'=>'ID Pangkalan Data Redis','Global Groups'=>'Kumpulan Global','Do Not Cache Groups'=>'Jangan Cache Kumpulan','Persistent Connection'=>'Sambungan Berterusan','Cache WP-Admin'=>'Cache WP-Admin','Purge All On Upgrade'=>'Kosongkan Semua Semasa Naik Taraf','Serve Stale'=>'Hidangkan Basi','Scheduled Purge URLs'=>'URL Pembersihan Terjadual','Scheduled Purge Time'=>'Masa Pembersihan Terjadual','Force Cache URIs'=>'Paksa URIs Cache','Force Public Cache URIs'=>'Paksa URI Cawangan Awam','Do Not Cache URIs'=>'Jangan Simpan dalam Cache URI','Do Not Cache Query Strings'=>'Jangan Simpan Cache Rentetan Pertanyaan','Do Not Cache Categories'=>'Jangan Cache Kategori','Do Not Cache Tags'=>'Jangan Simpan dalam Cache Tag','Do Not Cache Roles'=>'Jangan Simpan Peranan dalam Singgahan','CSS Minify'=>'Minifikasi CSS','CSS Combine'=>'Gabung CSS','CSS Combine External and Inline'=>'CSS Gabungkan Luaran dan Sebaris','Generate UCSS'=>'Jana UCSS','UCSS Inline'=>'UCSS Sebaris','UCSS Selector Allowlist'=>'Senarai Putih Pemilih UCSS','UCSS Inline Excluded Files'=>'Fail Pengecualian Sebaris UCSS','UCSS URI Excludes'=>'Pengecualian URI UCSS','JS Minify'=>'JS Minify','JS Combine'=>'Gabungan JS','JS Combine External and Inline'=>'Gabungkan JS Luaran dan Sebaris','HTML Minify'=>'Pengecilan HTML','HTML Lazy Load Selectors'=>'Pemilih Pemuatan Malas HTML','HTML Keep Comments'=>'Kekalkan Komen HTML','Load CSS Asynchronously'=>'Muat Turun CSS Se